// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AccountingClient) predicate.AccountingClient {
	return predicate.AccountingClient(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AccountingClient) predicate.AccountingClient {
	return predicate.AccountingClient(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AccountingClient) predicate.AccountingClient {
	return predicate.AccountingClient(sql.NotPredicates(p))
}
